hsd:
Geometry = GenFormat {
  <<< "geo.gen"
}
Hamiltonian = DFTB {
  SCC = Yes
  SCCTolerance = 1e-10
  MaxSCCIterations = 500
  ShellResolvedSCC = No
  Charge = 0.0
  SlaterKosterFiles = Type2FileNames {
    Prefix = "/tmp/pydftb_ref_j7bvb1fr/plain/"
    Separator = "-"
    Suffix = ".skf"
  }
  MaxAngularMomentum {
    Cu = "d"
    C = "p"
    O = "p"
  }
  Filling = Fermi {
    Temperature [K] = 300.0
  }
  SpinOrbit {
    Dual = Yes
    Cu [Hartree] = { 0.0 0.0 0.01 }
    C [Hartree] = { 0.0 0.004 }
    O [Hartree] = { 0.0 0.006 }
  }

}
Analysis {
  ResponseKernel {
  }
  PerturbSccTol = 1e-11
  MaxPerturbIter = 1000
  PrintForces = Yes
  MullikenAnalysis = Yes
}
Options {
  WriteDetailedOut = Yes
  WriteResultsTag = Yes
  TimingVerbosity = 0
}
ParserOptions {
  ParserVersion = 14
}
Parallel {
  UseOmpThreads = Yes
}
